"""Write and check the lock files that pin the emule image's downloads.

``pip`` turns pip installation reports, in installation order, into a
requirements file of exact wheel URLs and SHA-256 hashes. ``check-venv`` fails
unless the running interpreter's environment holds exactly those wheels'
versions. ``metal`` records what configuring tt-metal downloaded into its
source tree: each entry of the CPM source cache, by Git commit or content
digest, and the SFPI toolchain.
"""

import argparse
import hashlib
import json
import os
import re
import stat
import subprocess
import sys
from importlib import metadata
from pathlib import Path
from urllib.parse import unquote, urlsplit

GENERATED = "# Generated by scripts/update-tt-lang-emule-locks.sh; do not edit.\n"
PIP_HEADER = (
    "# Python environment of the tt-emule runtime image, resolved from\n"
    "# requirements-test.txt with CPU-only PyTorch.\n" + GENERATED
)
METAL_HEADER = (
    "# Dependencies that configuring tt-metal downloads for the tt-emule\n"
    "# runtime image, relative to the tt-metal source tree.\n" + GENERATED
)
PIP_ENTRY = re.compile(r"^(\S+) @ (https://\S+\.whl) \\$", re.MULTILINE)


def _fail(message: str) -> None:
    raise SystemExit(f"emule-lock: {message}")


def _canonical_name(name: str) -> str:
    return re.sub(r"[-_.]+", "-", name).lower()


def _wheel_entry(item: dict) -> tuple[str, str]:
    name = _canonical_name(item["metadata"]["name"])
    info = item["download_info"]
    url = info["url"]
    parts = urlsplit(url)
    archive = info.get("archive_info")
    if (
        archive is None
        or parts.scheme != "https"
        or parts.fragment
        or not parts.path.endswith(".whl")
    ):
        _fail(f"{name} must be locked to an HTTPS wheel download, not {url}")
    digest = archive.get("hashes", {}).get("sha256")
    if digest is None and archive.get("hash", "").startswith("sha256="):
        digest = archive["hash"].removeprefix("sha256=")
    if not digest or not re.fullmatch(r"[0-9a-f]{64}", digest):
        _fail(f"{name} has no SHA-256 hash in the installation report")
    return name, f"{name} @ {url} \\\n    --hash=sha256:{digest}\n"


def pip_lock(reports: list[Path]) -> str:
    entries: dict[str, str] = {}
    for report in reports:
        installed: dict[str, str] = {}
        for item in json.loads(report.read_text())["install"]:
            name, entry = _wheel_entry(item)
            if installed.setdefault(name, entry) != entry:
                _fail(f"{report} selects more than one file for {name}")
        # A later installation replaces the packages it upgrades.
        entries.update(installed)
    if not entries:
        _fail("the installation reports list no packages")
    return PIP_HEADER + "".join(entries[name] for name in sorted(entries))


def locked_versions(lock: Path) -> dict[str, str]:
    """Map each locked distribution to the version in its wheel file name."""
    versions = {}
    for name, url in PIP_ENTRY.findall(lock.read_text()):
        wheel = unquote(urlsplit(url).path.rsplit("/", 1)[1])
        versions[name] = wheel.split("-")[1]
    return versions


def check_venv(lock: Path) -> None:
    installed = {
        _canonical_name(distribution.metadata["Name"]): distribution.version
        for distribution in metadata.distributions()
    }
    installed.pop("pip", None)
    locked = locked_versions(lock)
    missing = sorted(set(locked.items()) - set(installed.items()))
    unexpected = sorted(set(installed.items()) - set(locked.items()))
    if missing or unexpected:
        _fail(
            f"the environment differs from {lock.name}: "
            f"missing {missing or 'nothing'}, unexpected {unexpected or 'nothing'}"
        )


def _file_digest(path: str) -> str:
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def _tree_digest(root: Path) -> str:
    digest = hashlib.sha256()

    def visit(directory: Path, prefix: str) -> None:
        for entry in sorted(os.scandir(directory), key=lambda entry: entry.name):
            path = prefix + entry.name
            mode = entry.stat(follow_symlinks=False).st_mode
            if stat.S_ISLNK(mode):
                record = f"link {path} {os.readlink(entry.path)}"
            elif stat.S_ISDIR(mode):
                record = f"dir {path}"
            elif stat.S_ISREG(mode):
                kind = "exec" if mode & 0o111 else "file"
                record = f"{kind} {path} {_file_digest(entry.path)}"
            else:
                _fail(f"unsupported file type: {entry.path}")
            digest.update(record.encode() + b"\0")
            if stat.S_ISDIR(mode):
                visit(Path(entry.path), path + "/")

    visit(root, "")
    return digest.hexdigest()


def _git_commit(checkout: Path) -> str:
    return subprocess.run(
        ["git", "-C", str(checkout), "rev-parse", "--verify", "HEAD^{commit}"],
        check=True,
        capture_output=True,
        text=True,
    ).stdout.strip()


def _pin(path: Path) -> str:
    mode = path.lstat().st_mode
    if stat.S_ISREG(mode):
        return f"sha256 {_file_digest(str(path))}"
    if not stat.S_ISDIR(mode):
        _fail(f"{path} is neither a regular file nor a directory")
    # A patched checkout keeps its commit.
    if (path / ".git").exists():
        return f"git {_git_commit(path)}"
    return f"tree-sha256 {_tree_digest(path)}"


def metal_lock(source: Path) -> str:
    cache = source / ".cpmcache"
    sfpi = source / "runtime" / "sfpi"
    if not cache.is_dir() or not sfpi.is_dir():
        _fail(f"{source} has no CPM source cache or SFPI toolchain")
    paths = []
    for child in sorted(cache.iterdir()):
        if child.is_dir() and not child.is_symlink():
            paths.extend(sorted(child.iterdir()))
        else:
            paths.append(child)
    paths.append(sfpi)
    return METAL_HEADER + "".join(
        f"{path.relative_to(source).as_posix()} {_pin(path)}\n" for path in paths
    )


def main(argv: list[str]) -> None:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    commands = parser.add_subparsers(dest="command", required=True)
    pip = commands.add_parser("pip", help="lock pip installation reports")
    pip.add_argument("reports", nargs="+", type=Path)
    venv = commands.add_parser("check-venv", help="compare this environment")
    venv.add_argument("lock", type=Path)
    metal = commands.add_parser("metal", help="lock tt-metal's downloads")
    metal.add_argument("source", type=Path)
    arguments = parser.parse_args(argv)
    if arguments.command == "pip":
        sys.stdout.write(pip_lock(arguments.reports))
    elif arguments.command == "check-venv":
        check_venv(arguments.lock)
    else:
        sys.stdout.write(metal_lock(arguments.source))


if __name__ == "__main__":
    main(sys.argv[1:])
